corrected_code:
from rest_framework.decorators import api_view, permission_classes
from rest_framework.permissions import IsAuthenticated
from rest_framework.response import Response
from rest_framework import status
from django.shortcuts import get_object_or_404
from django_fsm import can_proceed
from .models import EscrowContract

@api_view(['POST'])
@permission_classes([IsAuthenticated])
def release_contract_escrow(request, contract_id):
    contract = get_object_or_404(EscrowContract, id=contract_id)
    if contract.buyer != request.user and not request.user.is_staff:
        return Response({'error': 'Only the buyer or escrow mediator can release funds'}, status=status.HTTP_403_FORBIDDEN)

    if not can_proceed(contract.release_funds):
        return Response({'error': 'Escrow funds cannot be released in current state'}, status=status.HTTP_400_BAD_REQUEST)

    contract.release_funds(authorized_by=request.user)
    contract.save()
    return Response({'status': 'funds_released', 'state': contract.state})
